    left, right = ic0 - c0, c1 - ic1
    rr0, rr1 = max(0, r0 - top), min(h - 1, r1 + bottom)
    cc0, cc1 = max(0, c0 - left), min(w - 1, c1 + right)

    out = [row[:] for row in grid]
    for r in range(rr0, rr1 + 1):
        for c in range(cc0, cc1 + 1):
            if grid[r][c] == 0:
                out[r][c] = color
    return out
